void obrotomierz(int16_t kat1, int16_t kat2, uint16_t kolor, bool main = true) {
  int8_t step = (kat2 > kat1) ? 1 : -1;
  for (int16_t i = kat1; i != kat2; i += step) {
    int16_t id = i - KAT;
    int16_t id2 = i + 1 - KAT;
    if (main) {
    tft.drawLine(120 + RD(id, 0), 120 + RD(id, 1), 120 + RD(id2, 0), 120 + RD(id2, 1), kolor);
    tft.drawLine(120 + RD(id, 2), 120 + RD(id, 3), 120 + RD(id2, 2), 120 + RD(id2, 3), kolor);
    } else { 
    tft2.drawLine(120 + RD(id, 0), 120 + RD(id, 1), 120 + RD(id2, 0), 120 + RD(id2, 1), kolor);
    tft2.drawLine(120 + RD(id, 2), 120 + RD(id, 3), 120 + RD(id2, 2), 120 + RD(id2, 3), kolor);
    }
  }
}
